/* K07 round 3 — isolated accessibility-map prototype (view mode).
 * Data: window.K07_DATA from data.js (generated by scripts/build_data.py from stored K10 inputs).
 * All strings from data (names, addresses, categories) are inserted with textContent only.
 * Network distance is computed only if the graph check verdict is "routable"; for the stored K10 samples it is
 * "view_only", so the prototype shows straight-line distance as a lower bound and never calls anything unreachable.
 */
(function () {
  "use strict";
  const SVGNS = "http://www.w3.org/2000/svg";
  const $ = (id) => document.getElementById(id);
  const D = window.K07_DATA;

  function el(tag, attrs, text) {
    const e = document.createElement(tag);
    if (attrs) for (const [k, v] of Object.entries(attrs)) if (v !== undefined && v !== null) e.setAttribute(k, v);
    if (text !== undefined && text !== null) e.textContent = String(text);
    return e;
  }
  function sv(tag, attrs) {
    const e = document.createElementNS(SVGNS, tag);
    if (attrs) for (const [k, v] of Object.entries(attrs)) if (v !== undefined && v !== null) e.setAttribute(k, v);
    return e;
  }

  // ---------- error state: data missing ----------
  if (!D || !D.cities) {
    const main = document.querySelector("main");
    main.replaceChildren();
    const box = el("div", { class: "card err", role: "alert" });
    box.append(el("h2", null, "Данные не найдены"),
      el("p", null, "Файл data.js отсутствует или повреждён. Соберите его из сохранённых входов K10:"),
      el("code", null, "python3 research/round-3-results/K07/scripts/build_data.py"));
    main.append(box);
    return;
  }

  const SHAPES = { school: "circle", outpatient_clinic: "circle", preschool: "triangle", pharmacy: "triangle",
    college_university: "square", hospital: "square", government_office: "diamond" };
  const SECTOR_LABEL = { education: "образование", health: "здравоохранение", government: "госучреждения" };
  const STATE = { city: "shymkent", groups: new Set(Object.keys(D.groups)), roads: true, districts: true, clip: true,
    pointMode: false, point: null, T: 800, selected: null, view: null };

  // ---------- projection: local equirectangular metres around the city centre ----------
  let P = null;
  function setupProjection(city) {
    const c = D.cities[city];
    let w = 180, s = 90, e = -180, n = -90;
    for (const g of c.city_polygons) forEachCoord(g, (x, y) => { w = Math.min(w, x); e = Math.max(e, x); s = Math.min(s, y); n = Math.max(n, y); });
    const lon0 = (w + e) / 2, lat0 = (s + n) / 2, kx = Math.cos(lat0 * Math.PI / 180) * 111320, ky = 110574;
    P = { lon0, lat0, kx, ky, bbox: [w, s, e, n],
      fx: (lon) => (lon - lon0) * kx, fy: (lat) => (lat0 - lat) * ky,
      ix: (x) => x / kx + lon0, iy: (y) => lat0 - y / ky };
  }
  function forEachCoord(geom, f) {
    const polys = geom.type === "Polygon" ? [geom.coordinates] : geom.type === "MultiPolygon" ? geom.coordinates : [];
    for (const poly of polys) for (const ring of poly) for (const [x, y] of ring) f(x, y);
  }
  function fitView() {
    const svg = $("map"), W = svg.clientWidth || 800, H = svg.clientHeight || 500;
    const [w, s, e, n] = P.bbox;
    const x0 = P.fx(w), x1 = P.fx(e), y0 = P.fy(n), y1 = P.fy(s);
    const k = 0.92 * Math.min(W / (x1 - x0), H / (y1 - y0));
    STATE.view = { cx: (x0 + x1) / 2, cy: (y0 + y1) / 2, k };
  }
  function toScreen(lon, lat) {
    const svg = $("map"), W = svg.clientWidth, H = svg.clientHeight, v = STATE.view;
    return [(P.fx(lon) - v.cx) * v.k + W / 2, (P.fy(lat) - v.cy) * v.k + H / 2];
  }
  function toLonLat(sx, sy) {
    const svg = $("map"), W = svg.clientWidth, H = svg.clientHeight, v = STATE.view;
    return [P.ix((sx - W / 2) / v.k + v.cx), P.iy((sy - H / 2) / v.k + v.cy)];
  }

  // ---------- geometry helpers ----------
  function haversine(lon1, lat1, lon2, lat2) {
    const R = 6371008.8, r = Math.PI / 180, dφ = (lat2 - lat1) * r, dλ = (lon2 - lon1) * r;
    const a = Math.sin(dφ / 2) ** 2 + Math.cos(lat1 * r) * Math.cos(lat2 * r) * Math.sin(dλ / 2) ** 2;
    return 2 * R * Math.asin(Math.sqrt(a));
  }
  function inRing(x, y, ring) {
    let inside = false;
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const [xi, yi] = ring[i], [xj, yj] = ring[j];
      if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
    }
    return inside;
  }
  function inGeom(geom, x, y) {
    const polys = geom.type === "Polygon" ? [geom.coordinates] : geom.type === "MultiPolygon" ? geom.coordinates : [];
    return polys.some((poly) => inRing(x, y, poly[0]) && !poly.slice(1).some((h) => inRing(x, y, h)));
  }
  function geomPath(geom) {
    const polys = geom.type === "Polygon" ? [geom.coordinates] : geom.type === "MultiPolygon" ? geom.coordinates : [];
    let d = "";
    for (const poly of polys) for (const ring of poly) {
      ring.forEach(([x, y], i) => { const [sx, sy] = toScreen(x, y); d += (i ? "L" : "M") + sx.toFixed(1) + " " + sy.toFixed(1); });
      d += "Z";
    }
    return d;
  }
  function labelPoint(geom) {  // centroid of the largest outer ring (display only)
    const polys = geom.type === "Polygon" ? [geom.coordinates] : geom.coordinates;
    let best = null;
    for (const poly of polys) {
      const r = poly[0]; let A = 0, cx = 0, cy = 0;
      for (let i = 0, j = r.length - 1; i < r.length; j = i++) {
        const f = r[j][0] * r[i][1] - r[i][0] * r[j][1]; A += f; cx += (r[j][0] + r[i][0]) * f; cy += (r[j][1] + r[i][1]) * f;
      }
      if (!best || Math.abs(A) > Math.abs(best.A)) best = { A, x: cx / (3 * A), y: cy / (3 * A) };
    }
    return [best.x, best.y];
  }
  const fmtM = (m) => (m >= 1000 ? (m / 1000).toFixed(2).replace(".", ",") + " км" : Math.round(m) + " м");

  // ---------- marker ----------
  function markerShape(group, size) {
    const s = size, sh = SHAPES[group] || "circle";
    if (sh === "circle") return sv("circle", { r: s * 0.55 });
    if (sh === "square") return sv("rect", { x: -s / 2, y: -s / 2, width: s, height: s, rx: 1.5 });
    if (sh === "triangle") return sv("path", { d: `M0 ${-s * 0.62}L${s * 0.6} ${s * 0.42}L${-s * 0.6} ${s * 0.42}Z` });
    return sv("path", { d: `M0 ${-s * 0.65}L${s * 0.65} 0L0 ${s * 0.65}L${-s * 0.65} 0Z` });
  }
  function legendIcon(group) {
    const svg = sv("svg", { width: 16, height: 16, viewBox: "-8 -8 16 16", "aria-hidden": "true" });
    const m = markerShape(group, 11);
    m.setAttribute("fill", `var(--s-${D.groups[group].sector})`);
    m.setAttribute("stroke", "var(--surface)"); m.setAttribute("stroke-width", "1.5");
    svg.append(m);
    return svg;
  }

  // ---------- toolbar ----------
  function buildToolbar() {
    const seg = $("citySeg");
    for (const [key, c] of Object.entries(D.cities)) {
      const b = el("button", { type: "button", "aria-pressed": String(key === STATE.city), "data-city": key }, c.label);
      b.addEventListener("click", () => switchCity(key));
      seg.append(b);
    }
    const gf = $("groupFilters");
    for (const [g, info] of Object.entries(D.groups)) {
      const lab = el("label", { class: "chk" });
      const cb = el("input", { type: "checkbox", "data-group": g });
      cb.checked = true;
      cb.addEventListener("change", () => { cb.checked ? STATE.groups.add(g) : STATE.groups.delete(g); renderAll(); });
      lab.append(cb, legendIcon(g), document.createTextNode(info.label));
      gf.append(lab);
    }
    $("tRoads").addEventListener("change", (e) => { STATE.roads = e.target.checked; renderMap(); });
    $("tDistricts").addEventListener("change", (e) => { STATE.districts = e.target.checked; renderMap(); });
    $("tClip").addEventListener("change", (e) => { STATE.clip = e.target.checked; renderMap(); });
    $("pointBtn").addEventListener("click", () => {
      STATE.pointMode = !STATE.pointMode;
      $("pointBtn").setAttribute("aria-pressed", String(STATE.pointMode));
      $("map").classList.toggle("pointmode", STATE.pointMode);
    });
    $("thr").addEventListener("input", (e) => {
      STATE.T = +e.target.value; $("thrOut").textContent = STATE.T + " м";
      if (STATE.point) { renderMap(); renderSelection(); }
    });
    $("zIn").addEventListener("click", () => zoomBy(1.5));
    $("zOut").addEventListener("click", () => zoomBy(1 / 1.5));
    $("zReset").addEventListener("click", () => { fitView(); renderMap(); });
  }
  function switchCity(key) {
    STATE.city = key; STATE.point = null; STATE.selected = null;
    document.querySelectorAll("#citySeg button").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.city === key)));
    setupProjection(key); fitView(); renderAll();
  }
  function zoomBy(f, sx, sy) {
    const svg = $("map"), W = svg.clientWidth, H = svg.clientHeight, v = STATE.view;
    if (sx === undefined) { sx = W / 2; sy = H / 2; }
    const mx = (sx - W / 2) / v.k + v.cx, my = (sy - H / 2) / v.k + v.cy;
    v.k *= f; v.cx = mx - (sx - W / 2) / v.k; v.cy = my - (sy - H / 2) / v.k;
    renderMap();
  }

  // ---------- map ----------
  function visiblePlaces() { return D.cities[STATE.city].places.filter((p) => STATE.groups.has(p.group)); }

  function renderMap() {
    const c = D.cities[STATE.city], svg = $("map");
    svg.replaceChildren();
    const gCity = sv("g"), gDist = sv("g"), gRoad = sv("g"), gClip = sv("g"), gPoint = sv("g"), gMark = sv("g"), gLabel = sv("g");
    svg.append(gCity, gDist, gRoad, gClip, gPoint, gMark, gLabel);  // labels on top, with a surface halo
    for (const g of c.city_polygons) gCity.append(sv("path", { d: geomPath(g), fill: "var(--surface-2)", stroke: "var(--base)", "stroke-width": 1.5, "fill-rule": "evenodd" }));
    if (STATE.districts) for (const d of c.districts) {
      gDist.append(sv("path", { d: geomPath(d.geometry), fill: "none", stroke: "var(--muted)", "stroke-width": 1, "stroke-dasharray": "2 3" }));
      const [lx, ly] = labelPoint(d.geometry), [sx, sy] = toScreen(lx, ly);
      const t = sv("text", { x: sx, y: sy, "text-anchor": "middle", "font-size": 11, fill: "var(--muted)" });
      t.textContent = d.name; gDist.append(t);
    }
    if (STATE.roads) for (const s of c.segments) {
      let d = ""; s.coords.forEach(([x, y], i) => { const [a, b] = toScreen(x, y); d += (i ? "L" : "M") + a.toFixed(1) + " " + b.toFixed(1); });
      const vis = sv("path", { d, fill: "none", stroke: s.pedestrian_class ? "var(--ink-2)" : "var(--muted)", "stroke-width": 2,
        "stroke-linecap": "round", "stroke-dasharray": s.pedestrian_class ? "4 3" : null });
      const hit = sv("path", { d, fill: "none", stroke: "transparent", "stroke-width": 12, tabindex: 0, role: "button",
        "aria-label": `Дорога из выборки: ${s.class}, ${fmtM(s.length_m)}` });
      hit.style.cursor = "pointer";
      const tipText = () => [`${s.class}${s.name ? " · " + s.name : ""}`, `${fmtM(s.length_m)}, соединителей: ${s.connectors_count}`];
      hit.addEventListener("pointermove", (e) => showTip(e, tipText()));
      hit.addEventListener("pointerleave", hideTip);
      const pick = (e) => { e.stopPropagation(); STATE.selected = { type: "segment", id: s.id }; renderSelection(); };
      hit.addEventListener("click", pick);
      hit.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); pick(e); } });
      gRoad.append(vis, hit);
    }
    if (STATE.clip) {
      const cl = c.k10_request_clip;
      for (const [bb, dash, w] of [[cl.export, "6 4", 1.5], [cl.core, null, 1]]) {
        const [x0, y0] = toScreen(bb[0], bb[3]), [x1, y1] = toScreen(bb[2], bb[1]);
        gClip.append(sv("rect", { x: x0, y: y0, width: x1 - x0, height: y1 - y0, fill: "none", stroke: "var(--ink)", "stroke-width": w, "stroke-dasharray": dash }));
      }
      const [lx, ly] = toScreen(cl.export[0], cl.export[1]);  // below the export rectangle, away from the dense centre
      const t = sv("text", { x: lx, y: ly + 14, "font-size": 11, fill: "var(--ink)" });
      t.textContent = "Рамка запроса K10: выгрузка 6×6 км, ядро 4×4 км"; gLabel.append(t);
    }
    if (STATE.point) {
      const [plon, plat] = STATE.point, [sx, sy] = toScreen(plon, plat), rpx = STATE.T * STATE.view.k;
      gPoint.append(sv("circle", { cx: sx, cy: sy, r: rpx, fill: "none", stroke: "var(--ink)", "stroke-width": 1.5, "stroke-dasharray": "5 4" }));
      const t = sv("text", { x: sx + rpx * 0.71 + 4, y: sy - rpx * 0.71 - 4, "font-size": 11, fill: "var(--ink)" });
      t.textContent = `T = ${STATE.T} м по прямой (не зона пешей доступности)`; gLabel.append(t);
      gPoint.append(sv("path", { d: `M${sx - 8} ${sy}H${sx + 8}M${sx} ${sy - 8}V${sy + 8}`, stroke: "var(--ink)", "stroke-width": 2 }));
    }
    const places = visiblePlaces();
    for (const p of places) {
      const [sx, sy] = toScreen(p.lon, p.lat);
      const g = sv("g", { transform: `translate(${sx.toFixed(1)} ${sy.toFixed(1)})`, tabindex: 0, role: "button",
        "aria-label": `${p.name || "Без названия"}, ${p.group_label}`, "data-id": p.id });
      g.style.cursor = "pointer";
      const sel = STATE.selected && STATE.selected.type === "place" && STATE.selected.id === p.id;
      g.append(sv("circle", { r: 12, fill: "transparent" }));  // 24 px hit area
      if (sel) g.append(sv("circle", { r: 10, fill: "none", stroke: "var(--ink)", "stroke-width": 2 }));
      const m = markerShape(p.group, 11);
      m.setAttribute("fill", `var(--s-${p.sector})`); m.setAttribute("stroke", "var(--surface)"); m.setAttribute("stroke-width", "2");
      g.append(m);
      g.addEventListener("pointermove", (e) => showTip(e, [p.name || "Без названия", `${p.group_label} · conf. ${p.confidence}`]));
      g.addEventListener("pointerleave", hideTip);
      const pick = (e) => { e.stopPropagation(); STATE.selected = { type: "place", id: p.id }; renderMap(); renderSelection(); renderTable(); };
      g.addEventListener("click", pick);
      g.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); pick(e); } });
      gMark.append(g);
    }
    const msg = $("mapMsg");
    if (!STATE.groups.size) { msg.hidden = false; msg.textContent = "Не выбрана ни одна группа объектов — включите группы в панели фильтров."; }
    else if (!places.length) { msg.hidden = false; msg.textContent = "В выборке K10 нет объектов выбранных групп для этого города."; }
    else msg.hidden = true;
    $("attrib").textContent = "© OpenStreetMap contributors; Overture Maps Foundation · " + c.provenance.release;
  }

  // ---------- tooltip ----------
  function showTip(e, lines) {
    const tip = $("tip"), wrap = tip.parentElement.getBoundingClientRect();
    tip.replaceChildren(el("strong", null, lines[0]), ...lines.slice(1).map((l) => el("div", null, l)));
    tip.style.display = "block";
    const x = Math.min(e.clientX - wrap.left + 14, wrap.width - 270), y = e.clientY - wrap.top + 14;
    tip.style.left = Math.max(4, x) + "px"; tip.style.top = y + "px";
  }
  function hideTip() { $("tip").style.display = "none"; }

  // ---------- pan / zoom / point ----------
  function setupInteraction() {
    const svg = $("map");
    let drag = null;
    svg.addEventListener("pointerdown", (e) => { drag = { x: e.clientX, y: e.clientY, cx: STATE.view.cx, cy: STATE.view.cy, moved: false }; });
    svg.addEventListener("pointermove", (e) => {
      if (!drag || e.buttons === 0) return;
      const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
      if (Math.abs(dx) + Math.abs(dy) > 4) drag.moved = true;
      if (drag.moved) { STATE.view.cx = drag.cx - dx / STATE.view.k; STATE.view.cy = drag.cy - dy / STATE.view.k; renderMap(); }
    });
    svg.addEventListener("pointerup", (e) => {
      const d = drag; drag = null;
      if (!d || d.moved || !STATE.pointMode) return;
      if (e.target.closest && e.target.closest('[role="button"]')) return;  // a click on an object/road selects it, not a point
      const r = svg.getBoundingClientRect();
      STATE.point = toLonLat(e.clientX - r.left, e.clientY - r.top);
      STATE.selected = { type: "point" };
      renderMap(); renderSelection();
    });
    svg.addEventListener("wheel", (e) => {
      e.preventDefault();
      const r = svg.getBoundingClientRect();
      zoomBy(e.deltaY < 0 ? 1.2 : 1 / 1.2, e.clientX - r.left, e.clientY - r.top);
    }, { passive: false });
    window.addEventListener("resize", () => renderMap());
  }

  // ---------- side panel ----------
  function dlRows(dl, rows) {
    for (const [k, v, badge] of rows) {
      const dd = el("dd", null, v === null || v === undefined || v === "" ? "—" : v);
      if (badge) dd.append(el("span", { class: "badge" }, badge));
      dl.append(el("dt", null, k), dd);
    }
  }
  function renderSelection() {
    const c = D.cities[STATE.city], body = $("selBody"), empty = $("selEmpty");
    body.replaceChildren();
    const s = STATE.selected;
    empty.hidden = !!s;
    if (!s) return;
    if (s.type === "place") {
      const p = c.places.find((x) => x.id === s.id);
      if (!p) { empty.hidden = false; return; }
      body.append(el("h3", null, p.name || "Без названия"));
      const dl = el("dl");
      dlRows(dl, [
        ["Группа", `${p.group_label} (${SECTOR_LABEL[p.sector]})`, "правило K10"],
        ["Категория Overture", p.category, "наблюдение · вторичное"],
        ["Confidence", p.confidence, "оценка Overture 0..1"],
        ["Адрес", p.address, "наблюдение · вторичное"],
        ["Район", p.district_k07, "производное K07"],
        ["Координаты", `${p.lat.toFixed(6)}, ${p.lon.toFixed(6)}`, null],
        ["Мощность / места", "неизвестно", "нет источника"],
        ["Overture id", `${p.id} (v${p.overture_version})`, null],
      ]);
      body.append(dl, el("h3", null, "Источники записи"));
      const ul = el("ul", { class: "reasons" });
      for (const src of p.sources) ul.append(el("li", null, `${src.dataset} · ${src.license} · ${src.update_time ? src.update_time.slice(0, 10) : "дата неизвестна"}`));
      body.append(ul, el("p", { class: "muted" }, "Наличие в Overture не подтверждает, что объект работает; отсутствие объекта в выборке не означает, что его нет в городе."));
    } else if (s.type === "segment") {
      const g = c.segments.find((x) => x.id === s.id);
      body.append(el("h3", null, "Дорога из выборки K10"));
      const dl = el("dl");
      dlRows(dl, [
        ["Класс", g.class, "наблюдение · OSM через Overture"],
        ["Название", g.name, null],
        ["Длина", fmtM(g.length_m), "геодезическая, K10"],
        ["Соединители", `${g.connectors_count} (только число)`, "без id и позиции"],
        ["Право прохода пешком", "неизвестно", "нет access_restrictions"],
        ["Мост / тоннель", "неизвестно", "нет road_flags"],
        ["Источник", `${g.record_id || "—"} · ${g.license || "—"}`, null],
        ["Правка OSM", g.update_time ? g.update_time.slice(0, 10) : null, null],
      ]);
      body.append(dl);
    } else if (s.type === "point") {
      renderPointAnalysis(c, body);
    }
  }
  function renderPointAnalysis(c, body) {
    const [lon, lat] = STATE.point, T = STATE.T;
    body.append(el("h3", null, `Точка ${lat.toFixed(5)}, ${lon.toFixed(5)} · порог T = ${T} м`));
    const inside = c.city_polygons.some((g) => inGeom(g, lon, lat));
    if (!inside) body.append(el("p", { class: "warn" }, "Точка вне полигона города (Overture). Расчёт показан, но объекты за границей города в выборку K10 не входили."));
    const routable = c.graph.verdict === "routable";
    if (!routable) body.append(el("p", { class: "warn" }, "Расстояние по сети не рассчитано: вход не является пригодным пешеходным графом (см. «Пешеходный граф»). Ниже — расстояние по прямой: это нижняя граница пешего пути, а не доступность."));
    const rows = visiblePlaces().map((p) => ({ p, d: haversine(lon, lat, p.lon, p.lat) })).sort((a, b) => a.d - b.d);
    const within = rows.filter((r) => r.d <= T);
    if (!STATE.groups.size) { body.append(el("p", { class: "muted" }, "Не выбрана ни одна группа объектов.")); return; }
    if (!within.length) {
      body.append(el("p", { class: "muted" }, `В пределах ${T} м по прямой нет объектов выборки. Выборка K10 содержит до 15 объектов на группу; это не означает, что таких объектов рядом нет.`));
    }
    const tbl = el("table"), thead = el("thead"), tr = el("tr");
    for (const [h, cls] of [["Объект", null], ["Группа", null], ["Прямая", "num"], ["Сеть", "num"], ["≤ T", null]]) tr.append(el("th", { class: cls }, h));
    thead.append(tr); tbl.append(thead);
    const tb = el("tbody");
    for (const { p, d } of rows.slice(0, Math.max(within.length, 5))) {
      const r = el("tr");
      r.append(el("td", null, p.name || "Без названия"), el("td", null, p.group_label), el("td", { class: "num" }, fmtM(d)),
        el("td", { class: "num muted", title: "по сети не рассчитано: граф непригоден" }, routable ? "…" : "—"), el("td", null, d <= T ? "да" : "нет"));
      r.addEventListener("click", () => { STATE.selected = { type: "place", id: p.id }; renderMap(); renderSelection(); renderTable(); });
      tb.append(r);
    }
    tbl.append(tb); body.append(tbl);
    body.append(el("p", { class: "muted" }, `«Прямая» — расстояние по прямой; «Сеть» — по пешеходному графу${routable ? "" : " (не рассчитано: граф непригоден)"}; «≤ T» — по прямой. Показаны объекты в пределах T и не менее 5 ближайших. Это доступность в данном графе, не обеспеченность школьными местами. Объектов в выборке выбранных групп: ${rows.length}.`));
  }
  function renderGraph() {
    const c = D.cities[STATE.city], g = c.graph, b = $("graphBody");
    b.replaceChildren();
    const ok = g.verdict === "routable";
    const st = el("div", { class: "status" + (ok ? " ok" : ""), role: "status" });
    st.append(el("span", { class: "dot", "aria-hidden": "true" }), document.createTextNode(ok ? "Граф пригоден" : "Только просмотр данных"));
    b.append(st, el("p", null, `Проверка scripts/graph_check.py: ${g.segments} сегментов, ${String(g.km).replace(".", ",")} км. Вердикт: ${g.verdict}.`));
    const ul = el("ul", { class: "reasons" });
    for (const r of g.reasons_ru) ul.append(el("li", null, r));
    b.append(ul);
    const dg = g.diagnostics;
    b.append(el("p", { class: "muted" }, `Диагностика (граф по ней не строится): пересечений без общей вершины — ${dg.geometric_crossings_between_input_segments}; общих координат концов — ${dg.endpoint_coordinates_shared_by_2plus_segments}.`));
    const det = el("details"), sum = el("summary", null, "Запрос к K10 на связную выгрузку");
    const cl = c.k10_request_clip, dl = el("dl");
    dlRows(dl, [
      ["Выпуск", c.provenance.release, null],
      ["Ядро 4×4 км", cl.core.join(", "), "W, S, E, N"],
      ["Выгрузка 6×6 км", cl.export.join(", "), "W, S, E, N"],
      ["Центр", `${cl.centre[1]}, ${cl.centre[0]} — объектов выборки в 2 км: ${cl.objects_within_2km}`, "производное K07"],
      ["Типы", "transportation/segment (все в рамке), transportation/connector, places/place (все группы K10)", null],
      ["Столбцы", "connectors {connector_id, at}, access_restrictions, road_flags, level_rules, class, subclass, geometry, sources", null],
    ]);
    const a = el("a", { href: "../K10_REQUEST.md" }, "K10_REQUEST.md");
    det.append(sum, dl, el("p", null, "Полный текст: "), a);
    b.append(det);
  }
  function renderProvenance() {
    const c = D.cities[STATE.city], pv = c.provenance, k = c.counts, b = $("provBody");
    b.replaceChildren();
    const dl = el("dl");
    dlRows(dl, [
      ["Город", `${c.label} (${c.iso}), ${String(c.city_area_km2).replace(".", ",")} км²`, "полигон Overture/OSM"],
      ["Источник", `Overture Maps ${pv.release}`, "вторичный, не официальный"],
      ["Получено K10", `${(pv.retrieved_utc.places || "").replace("T", " ").slice(0, 16)} UTC`, null],
      ["Входы", `${D.inputs.k10_branch} @ ${D.inputs.k10_sha.slice(0, 7)}`, "копия: inputs/MANIFEST.json"],
      ["Объекты", pv.sampling.places, "выборка"],
      ["Дороги", pv.sampling.segments, "выборка"],
      ["Дороги в выборке", `${k.sample_segments} сегм., ${String(k.sample_road_km).replace(".", ",")} км из ${Math.round(k.extract_road_km_in_city)} км в городе`, "по E03 K10"],
      ["Районов", `${c.districts.length}`, "Overture/OSM, не акт"],
    ]);
    b.append(dl, el("h3", null, "Выборка и выгрузка K10 по группам"));
    const t = el("table"), th = el("thead"), tr = el("tr");
    for (const [h, cls] of [["Группа", null], ["В выборке", "num"], ["В выгрузке (районы)", "num"]]) tr.append(el("th", { class: cls }, h));
    th.append(tr); t.append(th);
    const tb = el("tbody");
    for (const [g, info] of Object.entries(D.groups)) {
      const r = el("tr");
      r.append(el("td", null, info.label), el("td", { class: "num" }, k.sample_by_group[g] || 0), el("td", { class: "num" }, k.extract_in_districts_by_group[g] || 0));
      tb.append(r);
    }
    t.append(tb); b.append(t);
    b.append(el("p", { class: "muted" }, "Даже полная выгрузка Overture — не реестр: по K10, полнота социальных объектов неизвестна и, вероятно, низкая."));
    const det = el("details"); det.append(el("summary", null, "Лицензии и ограничения"));
    const lic = el("ul", { class: "reasons" });
    lic.append(el("li", null, "Объекты: " + Object.entries(pv.licenses.places).map(([s, l]) => `${s} — ${l}`).join("; ")));
    lic.append(el("li", null, "Дороги: " + pv.licenses.segments));
    lic.append(el("li", null, "Районы: " + pv.licenses.divisions));
    lic.append(el("li", null, "Атрибуция: " + (pv.attribution || "—")));
    det.append(lic, el("h3", null, "Ограничения (из datasets.json K10)"));
    const lim = el("ul", { class: "reasons" });
    for (const part of ["places", "segments", "divisions"]) for (const l of pv.limitations[part]) lim.append(el("li", null, l));
    det.append(lim);
    b.append(det);
  }
  function renderTable() {
    const tb = $("tbl"), rows = visiblePlaces().slice().sort((a, b) => a.group.localeCompare(b.group) || (a.name || "").localeCompare(b.name || "", "ru"));
    tb.replaceChildren();
    $("tblCount").textContent = `(${rows.length} из ${D.cities[STATE.city].places.length} в выборке)`;
    if (!rows.length) {
      const tr = el("tr"); tr.append(el("td", { colspan: 4, class: "muted" }, STATE.groups.size ? "Нет объектов выбранных групп." : "Не выбрана ни одна группа объектов."));
      tb.append(tr); return;
    }
    for (const p of rows) {
      const tr = el("tr", { tabindex: 0 });
      if (STATE.selected && STATE.selected.type === "place" && STATE.selected.id === p.id) tr.classList.add("sel");
      tr.append(el("td", null, p.name || "Без названия"), el("td", null, p.group_label), el("td", null, p.district_k07), el("td", { class: "num" }, p.confidence));
      const pick = () => { STATE.selected = { type: "place", id: p.id }; renderMap(); renderSelection(); renderTable(); };
      tr.addEventListener("click", pick);
      tr.addEventListener("keydown", (e) => { if (e.key === "Enter") pick(); });
      tb.append(tr);
    }
  }
  function renderAll() { renderMap(); renderSelection(); renderGraph(); renderProvenance(); renderTable(); }

  buildToolbar();
  setupInteraction();
  setupProjection(STATE.city);
  fitView();
  renderAll();
  window.K07_APP = { state: STATE, switchCity, toScreen };  // for the headless user-path test
})();
